import{_ as a,c as t,o,a3 as i}from"./chunks/framework.Dk6sf0Ip.js";const u=JSON.parse('{"title":"20.2.01- Orden de abastecimiento","description":"","frontmatter":{},"headers":[],"relativePath":"flows/Mantenimiento/20.2.01-Orden-de-abastecimiento_Markdown.md","filePath":"flows/Mantenimiento/20.2.01-Orden-de-abastecimiento_Markdown.md","lastUpdated":1759238350000}'),d={name:"flows/Mantenimiento/20.2.01-Orden-de-abastecimiento_Markdown.md"};function r(n,e,s,l,c,m){return o(),t("div",null,e[0]||(e[0]=[i('<h1 id="_20-2-01-orden-de-abastecimiento" tabindex="-1">20.2.01- Orden de abastecimiento <a class="header-anchor" href="#_20-2-01-orden-de-abastecimiento" aria-label="Permalink to &quot;20.2.01- Orden de abastecimiento&quot;">​</a></h1><h2 id="creacion-de-la-orden-de-abastecimiento-oa" tabindex="-1">Creación de la Orden de Abastecimiento (OA) <a class="header-anchor" href="#creacion-de-la-orden-de-abastecimiento-oa" aria-label="Permalink to &quot;Creación de la Orden de Abastecimiento (OA)&quot;">​</a></h2><p>Esta funcionalidad permite al personal de Taller/Mantenimiento cargar formalmente los materiales (repuestos) o servicios necesarios para realizar el mantenimiento de un vehículo.</p><h3 id="_1-cabecera-de-la-solicitud" tabindex="-1">1. Cabecera de la Solicitud <a class="header-anchor" href="#_1-cabecera-de-la-solicitud" aria-label="Permalink to &quot;1. Cabecera de la Solicitud&quot;">​</a></h3><p>Esta sección vincula la necesidad de material o servicio a una Orden de Mantenimiento específica.</p><table tabindex="0"><thead><tr><th>Campo</th><th>Propósito</th><th>Instrucciones para Mantenimiento</th></tr></thead><tbody><tr><td>Solicitud N° / ID</td><td>Número de identificación de la OA.</td><td>Se genera automáticamente.</td></tr><tr><td>Fecha</td><td>Fecha de creación de la solicitud.</td><td>Fecha de creación de la solicitud.</td></tr><tr><td>Fecha Compromiso</td><td>Fecha límite para la recepción del material o servicio.</td><td>Fundamental para la planificación del taller.</td></tr><tr><td>Descripción</td><td>Resumen del motivo del abastecimiento.</td><td>Ej: Caja de Cambios.</td></tr><tr><td>Proveedor</td><td>Entidad a la que se le hará el pedido.</td><td>Seleccionar el proveedor.</td></tr><tr><td>Obs Actuar</td><td>Justificación de la solicitud.</td><td>Detalle el motivo.</td></tr><tr><td>Km / Hs</td><td>Lectura del vehículo al momento de la solicitud.</td><td>CRÍTICO: Registrar el Km del camión para el que se solicita el repuesto.</td></tr></tbody></table><h3 id="flujo-de-continuidad-proceso-integrado" tabindex="-1">Flujo de Continuidad (Proceso Integrado) <a class="header-anchor" href="#flujo-de-continuidad-proceso-integrado" aria-label="Permalink to &quot;Flujo de Continuidad (Proceso Integrado)&quot;">​</a></h3><p>La <strong>Orden de Abastecimiento (OA)</strong> es el documento que inicia el ciclo de reposición.</p><ol><li><p><strong>Activación de COMPRAS:</strong> El personal de Compras hace clic en el botón <strong>COMPRAS</strong> para generar la Orden de Compra (OC) y enviársela al encargado de compras.</p></li><li><p><strong>Man Presupuesto:</strong> por el momento sin uso \\</p></li></ol><p><strong>GUARDAR</strong> solo registra los cambios para uso personal o borrador, manteniendo la orden en su estado actual.</p><p><strong>SIGUIENTE</strong> formaliza la solicitud: <strong>cambia el estado</strong> de la orden (ej: a &quot;En Revisión&quot;) y la envía automáticamente a la siguiente área de gestión (ej: Supervisión o Compras) para su procesamiento.</p><p><strong>⚠️ No presione SIGUIENTE hasta que la solicitud esté completa y lista para ser gestionada.</strong></p>',12)]))}const h=a(d,[["render",r]]);export{u as __pageData,h as default};
